public sealed class MailCodeMethod(IMailer mailer) : ILoginMethod
{
    public string Provider => "mail-code";

    public async ValueTask<MethodResult> VerifyAsync(LoginRequest request, ILoginSource source, CancellationToken token = default)
    {
        var subject = await source.FindAsync(request.Identifier, token);

        if (subject is null)
            return MethodResult.Failed(LoginState.InvalidCred, IdentityCodes.SecReason.NoUser);

        var code = RandomNumberGenerator.GetInt32(100_000, 1_000_000).ToString(System.Globalization.CultureInfo.InvariantCulture);

        await mailer.SendAsync(subject.UserName, code);

        return MethodResult.Challenge(subject, IdentityCodes.Challenge.Otp, code);
    }
}

